'use strict';
let partyData,partyError=false,partyLoading=false;
const partyState={query:'',kind:'all'};
const kindLabels={program:'事業の経費',contract:'契約金額',receipt:'受取側の収入実績'};
async function loadParties(){if(partyLoading)return;partyLoading=true;try{const r=await fetch('transactions.json');if(!r.ok)throw Error();partyData=await r.json()}catch(e){partyError=true}finally{partyLoading=false;if(state.tab==='parties')render()}}
function partiesView(){
 if(state.city!=='13105'||state.year!=='2024')return `<div class="section-top"><h2>個別事業・契約先・支払先</h2>${tag('収録範囲を確認')}</div><section class="panel"><h3>この自治体・年度の相手先資料は未収録です。</h3><p>全国の支出統計とは別に、個別資料を確認して接続しています。現在は文京区2024年度の資料をご覧いただけます。</p><button class="action" id="partyBunkyo">文京区2024年度を見る →</button></section>`;
 if(!partyData){if(!partyError)loadParties();return `<section class="panel"><h2>個別事業・契約先・支払先</h2><p role="status">${partyError?'資料を読み込めませんでした。':'事業と相手先の資料を読み込んでいます…'}</p>${partyError?'<button id="partyRetry" class="action">再読み込み</button>':''}</section>`}
 const q=partyState.query.trim(),records=partyData.records.filter(r=>(partyState.kind==='all'||r.kind===partyState.kind)&&(!q||[r.name,r.party,kindLabels[r.kind]].join(' ').includes(q)));
 const row=r=>`<details class="party-record"><summary><span class="party-label">${tag(kindLabels[r.kind],r.kind==='receipt'?'green':'')}<b>${esc(r.name)}</b><small>${r.party?'相手先：'+esc(r.party):'契約先・支払先：未確認'}</small></span><strong>${fmt(r.amount)}<small>円</small></strong></summary><div class="party-body">${r.party?`<div class="party-branch"><span>${r.kind==='contract'?'契約先':'指定管理者・収入計上先'}</span><b>${esc(r.party)}</b><p>${r.kind==='receipt'?'管理運営の実績報告で施設・団体・収入の関係を確認。':'公表された同じ案件行で、業務名・契約先・金額の関係を確認。'}</p></div>`:'<div class="party-branch"><b>相手先への接続待ち</b><p>事業名と経費は確認済みです。個人受給者や委託先の名前は、この見出しからは特定できません。</p></div>'}${r.components?.length?`<p class="small">内訳：${r.components.map(([n,v])=>esc(n)+' '+fmt(v)+'円').join(' ／ ')}（表示額に含む）</p>`:''}<p class="small">${esc(r.note)}</p><p>${link(r.url+(r.page?'#page='+r.page:''),r.page?'原資料PDF p.'+r.page:'原資料の案件一覧')} <span class="small">${esc(r.evidence)}</span></p><p class="small">対象：2024年度 ／ 確認日：${partyData.retrieved} ／ ID：${r.id}</p></div></details>`;
 const renderGroup=(kind,title,desc)=>{const list=records.filter(r=>r.kind===kind);if(!list.length)return '';let contents=list.map(row).join('');if(kind==='program'){const pages=[...new Set(list.map(r=>r.page))];contents=pages.map(p=>{const group=list.filter(r=>r.page===p);return `<details class="party-page" ${q?'open':''}><summary>主要施策の概要 · PDF p.${p}<span>${group.length}件</span></summary><div>${group.map(row).join('')}</div></details>`}).join('')}return `<section class="panel party-group"><div class="section-top"><h3>${title}</h3>${tag(list.length+'件')}</div><p class="small">${desc}</p>${contents}</section>`};
 return `<div class="section-top"><h2>事業の先の、相手先まで。</h2>${tag('文京区 · 2024年度','green')}</div><p>枝を開くと、個別の業務・施設から契約先や収入計上先、根拠資料へ進めます。</p><div class="stats party-stats">${[['program','主要施策の見出し'],['contract','契約先を確認'],['receipt','収入実績を確認']].map(([k,n])=>`<button class="stat ${partyState.kind===k?'primary':''}" data-party-kind="${k}"><span class="label">${n}</span><strong>${partyData.records.filter(r=>r.kind===k).length}<small> 件</small></strong><span>${kindLabels[k]}</span></button>`).join('')}</div><div class="note blue">契約金額・事業の経費・指定管理料収入は異なる段階の数字です。合算しません。「収入実績」は受取側の報告に基づき、銀行振込や自治体の支払伝票まで確認したものではありません。</div><section class="panel"><div class="tree-tools"><input type="search" id="partySearch" value="${esc(q)}" placeholder="事業名・会社名・団体名で検索" aria-label="事業名や相手先を検索"><select id="partyKind" aria-label="金額区分"><option value="all">すべての区分</option>${Object.entries(kindLabels).map(([k,v])=>`<option value="${k}" ${partyState.kind===k?'selected':''}>${v}</option>`).join('')}</select><button class="mini-btn" id="partyCsv">表示結果をCSV</button></div><p class="small" role="status">${records.length}件を表示。${esc(partyData.coverage)}</p></section>${renderGroup('receipt','受取先をたどる','施設の管理運営 → 指定管理者 → 指定管理料収入。12報告のR6欄を確認。返還額が別掲される場合は明記しています。')}${renderGroup('contract','契約先をたどる','個別業務 → 契約先 → 公表契約金額。優良委託の掲載案件に限定しています。')}${renderGroup('program','個別事業の経費をたどる','主要施策の概要の「経費」付き見出しをページごとに表示。重複する施策・内数を含むため総額は算出しません。')}${!records.length?'<div class="empty">一致する事業・相手先がありません。</div>':''}<div class="note">全国統計の「委託料」「公園費」などと各レコードを結ぶ会計コードは未照合です。金額や名称が似ているだけで、統計細目の子項目には接続していません。</div><p class="small">${link('transactions.json','全レコード・資料ハッシュ（JSON）')} ／ ${link('https://www.city.bunkyo.lg.jp/b007/p006466/index.html','指定管理者の評価一覧')}。目白台交流館は一覧ページとPDFの団体名が異なるため、対象年度のPDFの記載を採用しています。</p>`
}
function bindParties(){
 const on=(s,e,f)=>{const el=$(s);if(el)el.addEventListener(e,f)};
 on('#partyBunkyo','click',()=>{state.city='13105';state.year='2024';$('#pref').value='';$('#search').value='';$('#year').value='2024';fillCities()});
 on('#partyRetry','click',()=>{partyError=false;render()});on('#openParties','click',()=>setTab('parties'));
 on('#partySearch','input',e=>{const pos=e.target.selectionStart;partyState.query=e.target.value;render();$('#partySearch').focus();$('#partySearch').setSelectionRange(pos,pos)});
 on('#partyKind','change',e=>{partyState.kind=e.target.value;render()});document.querySelectorAll('[data-party-kind]').forEach(b=>b.addEventListener('click',()=>{partyState.kind=partyState.kind===b.dataset.partyKind?'all':b.dataset.partyKind;render()}));
 on('#partyCsv','click',()=>{const rows=[['年度','自治体','区分','事業・業務名','相手先','金額（円）','資料URL','PDFページ','根拠欄','注記'],...partyData.records.filter(r=>(partyState.kind==='all'||r.kind===partyState.kind)&&(!partyState.query.trim()||[r.name,r.party,kindLabels[r.kind]].join(' ').includes(partyState.query.trim()))).map(r=>['2024','文京区',kindLabels[r.kind],r.name,r.party||'未確認',r.amount,r.url,r.page||'',r.evidence,r.note])];const content='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='bunkyo-2024-parties.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
}
